{
  "meta": {
    "authoring": "Fable 5.1 compact fixture corrections via the Claude.ai Max bridge. Both prior advisory results are retained unchanged as history. No R15 implementation or design supplied; no tools used; no files written; no provider experiment. Fictional test data corrections only. Execution pending.",
    "scope": "Replaces only the fields/variants named below. All other FX-A2 and FX-C2 content stands as previously authored."
  },
  "fixture_corrections": {
    "FX-A2": {
      "replace_variants": {
        "A2-scope-contradiction": {
          "spec": "Replace the third sentence with: 'If the district's hardship review board has issued a written hardship waiver to a family, the published-schedule condition and the separate-accounting condition do not apply to that family's fee; every other condition and the no-fee protections continue to apply to that family, and the separate-accounting condition continues to apply to that family.' Keep the fourth sentence ('Offering a hardship review does not by itself constitute a waiver.') unchanged.",
          "reason": "The prior wording relied on reading 'every other condition' as including separate accounting, which it naturally excludes. The source must itself state that separate accounting both does not apply and continues to apply under W.",
          "expected": {
            "waived_under_W": "A3 (published schedule) unambiguously; A6 (separate accounting) CONTRADICTORY — source states both 'do not apply' and 'continues to apply' for the same family under the same trigger",
            "still_required_under_W": "A1, A2, A4, A5 explicitly; A6 contradictory, not asserted either way",
            "X1..X3": "still block",
            "trigger": "W = issued written hardship waiver; A5 offering ≠ W (fourth sentence retained)",
            "atom_coverage": "all baseline atoms A1..A6, X1..X3 and W present",
            "outcomes": "PRESERVED only if both A6 statements are carried with an uncertainty/contradiction marker; choosing either A6 reading silently is COLLAPSED; dropping one statement is SILENT-LOSS; treating 'every other condition' phrasing as the contradiction is not a basis for any verdict"
          },
          "checks": {"automatic": ["both A6 statements present (grounded spans)", "A6 marked contradictory/uncertain", "A3 waived under W", "A1, A2, A4, A5 still required", "W ≠ A5"], "advisory": ["form and wording of the contradiction marker"]}
        },
        "A2-scope-coherent": {
          "spec": "Replace the third sentence with: 'If the district's hardship review board has issued a written hardship waiver to a family, the published-schedule condition and the separate-accounting condition do not apply to that family's fee; the district-eligibility condition, the state-funded-classroom condition, the written-notice condition, the hardship-review-offer condition, and the no-fee protections continue to apply to that family.' Keep the fourth sentence unchanged.",
          "reason": "States every retained condition explicitly so the coherent scope change does not depend on interpreting 'other'.",
          "expected": {
            "waived_under_W": "A3, A6",
            "still_required_under_W": "A1, A2, A4, A5 (each named in source)",
            "X1..X3": "still block",
            "trigger": "W; A5 ≠ W",
            "atom_coverage": "all baseline atoms, X1..X3 and W present; no contradiction marker expected",
            "outcomes": "PRESERVED if waived set = {A3, A6} and retained set = {A1, A2, A4, A5}; A6 appearing in the retained set is INVERTED; a contradiction marker on A6 here is a false-uncertainty finding, recorded for advisory review"
          },
          "checks": {"automatic": ["waived-set equality", "retained-set equality", "W ≠ A5"], "advisory": ["representation of waived state"]}
        }
      },
      "unchanged_variants": ["A2-trigger-conflate", "A2-district-wide-leak"],
      "unchanged_fields": ["source (base text)", "expected (base)", "checks (base)"]
    },
    "FX-C2": {
      "choice": "Option 1: change the fourth sentence to a grammatical bare imperative while keeping the proposed-only umbrella.",
      "replace_source": "Each of the following four requirements is part of the proposed rule and is not currently in effect. First, organizations must submit annual records if they served more than twenty participants and received state funds. Second, organizations receiving only private funds may submit records voluntarily. Third, organizations should retain supporting worksheets. Fourth, send requests to the office by the stated date.",
      "reason": "The prior fourth sentence ('organizations send requests ...') was declarative prose, not a bare imperative, so it could not test imperative-force ambiguity. The umbrella sentence is retained so proposed status for all four items remains explicit.",
      "replace_expected": {
        "status": "proposed for all four items, explicit via umbrella; 'not currently in effect' preserved as a separate fact",
        "modals": {
          "C1": "must (mandatory)",
          "C2": "may (voluntary)",
          "C3": "should (recommended, not mandatory)",
          "C4": "bare imperative. Allowed labels: unspecified | mandatory-with-explicit-ambiguity | advisory-with-explicit-ambiguity | imperative-unlabeled. Forbidden: a force label without an ambiguity marker; dropping the directive; labeling C4 (or C2, C3) mandatory on the basis that the umbrella calls the items 'requirements'"
        },
        "umbrella_rule": "The word 'requirements' in the umbrella sentence fixes status (proposed, not in effect), not force. Force is read per item from its own modal or imperative. An inventory that upgrades C2 'may' or C3 'should' or C4 to mandatory because of the heading is INVERTED.",
        "operator_C1": "AND",
        "comparator": ">20 strict",
        "deadline_ref_C4": "'the stated date' unresolved; identifier retained; no date fabricated"
      },
      "variants_adjust": {
        "C2-partial-scope": {"note": "unchanged spec; with the new fourth sentence, C4 status becomes unspecified under this variant and its force expectation is unchanged"},
        "C2-status-contradiction": {"note": "unchanged"},
        "add": {
          "v": "C2-heading-force-bait",
          "spec": "Replace 'four requirements' in the umbrella with 'four mandatory requirements'; leave items unchanged.",
          "expected": "Umbrella force claim ('mandatory') and per-item modals ('may', 'should', bare imperative) are both preserved; C2/C3/C4 force marked CONTRADICTORY or uncertain rather than silently upgraded to mandatory; C1 unaffected. COLLAPSED if items are uniformly labeled mandatory without uncertainty.",
          "checks": {"automatic": ["per-item modal retained", "umbrella claim present", "contradiction/uncertainty marker on C2, C3, C4"], "advisory": ["marker wording"]}
        }
      },
      "unchanged_fields": ["families", "checks (base)"]
    }
  },
  "status": "Fictional fixture corrections only. No additional test families, no reference labels, no implementation approval, no performance claim. Execution remains pending supply of an implementation."
}

